import json

def transform(grid):
    height, width = len(grid), len(grid[0])

    # Find all 5 positions
    fives = [(r,c) for r in range(height) for c in range(width) if grid[r][c] == 5]

    if not fives:
        return [row[:] for row in grid]

    # Reference marker is top-left-most 5
    reference = min(fives, key=lambda x: (x[0], x[1]))

    # Other 5s determine the shift
    other_fives = [f for f in fives if f != reference]

    result = [[0]*width for _ in range(height)]

    # Keep the original input grid first (everything)
    for r in range(height):
        for c in range(width):
            result[r][c] = grid[r][c]

    # For each other 5, compute shift and copy non-marker cells
    for (oc, gc) in other_fives:
        shift_r = oc - reference[0]
        shift_c = gc - reference[1]

        # Copy ALL non-marker cells
        for r in range(height):
            for c in range(width):
                if grid[r][c] != 0 and grid[r][c] != 5:
                    new_r = r + shift_r
                    new_c = c + shift_c
                    if 0 <= new_r < height and 0 <= new_c < width:
                        result[new_r][new_c] = grid[r][c]

    return result

