def transform_copy_all_non5(demo_in):
    """
    Rule: Copy ALL non-0-non-5 cells and shift them by (marker2 - marker1).
    Keep original cells and added copy. Keep both markers.
    """
    height, width = len(demo_in), len(demo_in[0])
    fives = [(r,c) for r in range(height) for c in range(width) if demo_in[r][c] == 5]
    if len(fives) < 2:
        return [row[:] for row in demo_in]

    marker1, marker2 = fives[0], fives[1]
    shift_r, shift_c = marker2[0] - marker1[0], marker2[1] - marker1[1]

    # Build result: start with background
    result = [[0]*width for _ in range(height)]

    # Keep all original non-5 cells
    for r in range(height):
        for c in range(width):
            if demo_in[r][c] != 0 and demo_in[r][c] != 5:
                result[r][c] = demo_in[r][c]

    # Add shifted copy
    for r in range(height):
        for c in range(width):
            if demo_in[r][c] != 0 and demo_in[r][c] != 5:
                new_r, new_c = r + shift_r, c + shift_c
                if 0 <= new_r < height and 0 <= new_c < width:
                    result[new_r][new_c] = demo_in[r][c]

    # Place markers
    for mr, mc in fives:
        result[mr][mc] = 5

    return result

